1	package sandbox
2	
3	import (
4		"bytes"
5		"context"
6		"fmt"
7		"log/slog"
8		"os"
9		"os/exec"
10		"path/filepath"
11		"strconv"
12		"strings"
13		"sync"
14		"time"
15	)
16	
17	// Language identifies a supported runtime.
18	type Language string
19	
20	const (
21		// Orva offers exactly two runtimes, latest-stable only: `node` (Node.js 24)
22		// and `python` (Python 3.14). The identifier is generic on purpose — the
23		// concrete version is an implementation detail that tracks latest-stable and
24		// is surfaced only as a display label (see handlers/runtimes.go). Legacy
25		// versioned IDs (node22/node24/python313/python314) are rewritten to these
26		// at startup — see migrations.go.
27		Node   Language = "node"
28		Python Language = "python"
29	)
30	
31	// IsNode reports whether a language is the Node runtime.
32	func (l Language) IsNode() bool { return l == Node }
33	
34	// IsPython reports whether a language is the Python runtime.
35	func (l Language) IsPython() bool { return l == Python }
36	
37	// ExecConfig holds everything needed to run user code in nsjail.
38	type ExecConfig struct {
39		Language  Language
40		CodeDir   string // Directory containing user code
41		Stdin     []byte // Request JSON piped to stdin
42		Timeout   time.Duration
43		MemoryMB  int
44		MaxPids   int
45		MaxCPUs   float64 // 0 = no cpu cap; positive = fractional CPUs allowed (e.g. 0.5)
46	
47		// Env holds environment variables injected into the sandbox. Includes
48		// both function config env_vars and decrypted secrets at invoke time.
49		Env map[string]string
50	
51		// Seccomp policy (Kafel string). Empty means no seccomp filter.
52		SeccompPolicy string
53	
54		// NetworkMode controls the sandbox's network access. "" or "none"
55		// keeps the function in an isolated net namespace with only loopback
56		// (the safe default — blocks egress and exfil). "egress" adds nsjail's
57		// --use_pasta flag, which gives the sandbox a userspace TCP/UDP stack
58		// that NATs out via the host without exposing host interfaces.
59		NetworkMode string
60	
61		// ResolvConfPath, when non-empty AND NetworkMode=="egress", is the
62		// path of an operator-managed resolv.conf bind-mounted into the
63		// sandbox at /etc/resolv.conf. Generated by the firewall manager
64		// from system_config.dns_servers. Empty falls back to whatever the
65		// rootfs ships (usually nothing meaningful for slim images).
66		ResolvConfPath string
67	
68		// HostsPath, when non-empty AND NetworkMode=="egress", is bind-mounted
69		// at /etc/hosts so operator-defined host→IP overrides take precedence
70		// over upstream DNS. Generated by the firewall manager from
71		// system_config.dns_records.
72		HostsPath string
73	
74		// Paths (populated from config at startup).
75		NsjailBin string
76		RootfsDir string // e.g. ~/.orva/rootfs
77	}
78	
79	// ExecResult holds the outcome of a sandboxed execution.
80	type ExecResult struct {
81		Stdout   []byte
82		Stderr   []byte
83		ExitCode int
84		Duration time.Duration
85		TimedOut bool
86		Error    error
87	}
88	
89	// Execute runs user code inside an nsjail sandbox. Each call spawns a
90	// fresh process — no daemon, no pool.
91	func Execute(ctx context.Context, cfg ExecConfig) *ExecResult {
92		start := time.Now()
93	
94		if cfg.Timeout == 0 {
95			cfg.Timeout = 30 * time.Second
96		}
97		if cfg.MemoryMB == 0 {
98			cfg.MemoryMB = 64
99		}
100		if cfg.MaxPids == 0 {
101			cfg.MaxPids = 32
102		}
103	
104		rootfs, entrypoint, err := resolveRuntime(cfg)
105		if err != nil {
106			return &ExecResult{Error: err, Duration: time.Since(start)}
107		}
108	
109		args := buildArgs(cfg, rootfs, entrypoint)
110	
111		ctx, cancel := context.WithTimeout(ctx, cfg.Timeout+5*time.Second)
112		defer cancel()
113	
114		// nsjail itself carries the required capabilities via setcap (installed
115		// by `orva setup` or baked into the Docker image). No sudo wrapper.
116		cmd := exec.CommandContext(ctx, cfg.NsjailBin, args...)
117	
118		var stdout, stderr bytes.Buffer
119		cmd.Stdout = &stdout
120		cmd.Stderr = &stderr
121		if len(cfg.Stdin) > 0 {
122			cmd.Stdin = bytes.NewReader(cfg.Stdin)
123		}
124	
125		err = cmd.Run()
126	
127		result := &ExecResult{
128			Stdout:   stdout.Bytes(),
129			Stderr:   stderr.Bytes(),
130			Duration: time.Since(start),
131		}
132	
133		if err != nil {
134			if exitErr, ok := err.(*exec.ExitError); ok {
135				result.ExitCode = exitErr.ExitCode()
136			} else {
137				result.Error = err
138			}
139			if ctx.Err() == context.DeadlineExceeded {
140				result.TimedOut = true
141			}
142		}
143	
144		return result
145	}
146	
147	func resolveRuntime(cfg ExecConfig) (rootfs, entrypoint string, err error) {
148		switch cfg.Language {
149		case Python:
150			rootfs = filepath.Join(cfg.RootfsDir, string(cfg.Language))
151			entrypoint = "/usr/local/bin/python3"
152		case Node:
153			rootfs = filepath.Join(cfg.RootfsDir, string(cfg.Language))
154			entrypoint = "/usr/local/bin/node"
155		default:
156			return "", "", fmt.Errorf("unsupported language: %s", cfg.Language)
157		}
158	
159		if _, err := os.Stat(rootfs); err != nil {
160			return "", "", fmt.Errorf("rootfs not found at %s: %w", rootfs, err)
161		}
162		return rootfs, entrypoint, nil
163	}
164	
165	func buildArgs(cfg ExecConfig, rootfs, entrypoint string) []string {
166		// Rely on user namespaces instead of setcap to grant nsjail the caps it
167		// needs for mount/chroot. This works both on bare Linux hosts with
168		// unprivileged_userns_clone=1 AND inside Docker with --cap-add SYS_ADMIN
169		// (where file capabilities don't transfer across fork/exec from a
170		// non-root parent). If you need to force the old setcap-based model
171		// (e.g., kernel has no user namespaces), set ORVA_DISABLE_USERNS=1.
172		//
173		// NOTE: --time_limit intentionally dropped; Go-side context.WithTimeout
174		// + Worker.Kill() handles timeouts with millisecond resolution and
175		// avoids the skew from nsjail's whole-second limit.
176		args := []string{
177			"-Mo",
178			"--chroot", rootfs,
179			"-R", cfg.CodeDir + ":/code",
180			"-T", "/tmp",
181			"--rlimit_as", "max",
182			"-Q",
183		}
184		if os.Getenv("ORVA_DISABLE_USERNS") == "1" {
185			args = append(args, "--disable_clone_newuser")
186		}
187	
188		// Per-function egress. nsjail's default already creates a fresh net
189		// namespace with only loopback; --user_net layers a userspace TCP/UDP
190		// stack (nsjail's bundled "nstun" backend) on top so the function can
191		// reach external APIs without ever touching a host interface.
192		// Functions that don't need network access stay loopback-only —
193		// that's the safe default and blocks data exfiltration from
194		// compromised handlers. Requires /dev/net/tun in the container; the
195		// entrypoint mknods it on startup.
196		if cfg.NetworkMode == "egress" {
197			args = append(args, "--user_net")
198			// Bind-mount the firewall-managed resolv.conf so the function's
199			// DNS resolver matches what the operator configured. nsjail's
200			// -R takes <src>:<dst>; we mount over /etc/resolv.conf inside
201			// the chroot. Skip silently if the file isn't on disk yet — the
202			// firewall manager writes it on its first refresh tick, so a
203			// fresh boot may briefly fall back to the rootfs's default.
204			if cfg.ResolvConfPath != "" {
205				if _, err := os.Stat(cfg.ResolvConfPath); err == nil {
206					args = append(args, "-R", cfg.ResolvConfPath+":/etc/resolv.conf")
207				}
208			}
209			// /etc/hosts overrides — the resolver consults files before DNS by
210			// default, so any host→IP record in this file beats whatever the
211			// upstream resolver returns. Same skip-if-missing posture as resolv.
212			if cfg.HostsPath != "" {
213				if _, err := os.Stat(cfg.HostsPath); err == nil {
214					args = append(args, "-R", cfg.HostsPath+":/etc/hosts")
215				}
216			}
217		}
218	
219		// Cgroup v2 resource limits — only enabled if we have a writable cgroup
220		// delegate (systemd user slice on most modern hosts; bind-mounted in the
221		// Docker image). Without delegation nsjail can't create the NSJAIL.<pid>
222		// cgroup, so rather than crashing we silently drop the memory/pid caps.
223		// The process-level rlimit_as flag above still bounds address-space.
224		if mount := cgroupv2Delegate(); mount != "" {
225			// cgroup v2 memory.max at 1.5× the declared memory. This gives the
226			// kernel headroom to reclaim via PSI pressure before OOM-killing,
227			// and matches the 1.5× per-worker budget the autoscaler uses for
228			// admission control.
229			memMaxBytes := int64(cfg.MemoryMB) * 1024 * 1024 * 3 / 2
230			args = append(args,
231				"--use_cgroupv2",
232				"--cgroupv2_mount", mount,
233				"--cgroup_mem_max", fmt.Sprintf("%d", memMaxBytes),
234				"--cgroup_pids_max", fmt.Sprintf("%d", cfg.MaxPids),
235			)
236			// Use cgroup CPU bandwidth (cpu.max) instead of --max_cpus. The
237			// --max_cpus flag is an affinity mask that pins the process to a
238			// subset of cores — actively harmful under concurrency because the
239			// kernel can't load-balance across the full CPU set. Bandwidth
240			// limits (microseconds per period) are what fractional CPU means.
241			if msPerSec := int(cfg.MaxCPUs * 1000); msPerSec > 0 {
242				// nsjail --cgroup_cpu_ms_per_sec = ms of CPU per 1000 ms window.
243				// Supports fractional CPUs: 0.5 → 500, 0.25 → 250.
244				args = append(args,
245					"--cgroup_cpu_ms_per_sec",
246					fmt.Sprintf("%d", msPerSec),
247				)
248			}
249		}
250	
251		if cfg.SeccompPolicy != "" {
252			args = append(args, "--seccomp_string", cfg.SeccompPolicy)
253		}
254	
255		// Inject env vars + secrets. nsjail takes --env KEY=VAL; an --env with
256		// no '=' passes the host-side value through, which we never want for
257		// security. Always format as KEY=VAL explicitly.
258		for k, v := range cfg.Env {
259			if k == "" {
260				continue
261			}
262			args = append(args, "--env", k+"="+v)
263		}
264		// Also tell the Python/Node adapter about Orva context via env.
265		args = append(args,
266			"--env", "ORVA_FUNCTION_ID="+getenvOr(cfg.Env, "ORVA_FUNCTION_ID", ""),
267			"--env", "ORVA_EXECUTION_ID="+getenvOr(cfg.Env, "ORVA_EXECUTION_ID", ""),
268		)
269	
270		args = append(args, "--", entrypoint)
271	
272		switch {
273		case cfg.Language.IsPython():
274			args = append(args, "/opt/orva/adapter.py")
275		case cfg.Language.IsNode():
