287	// cgroupv2Delegate returns a cgroup v2 path this process can create children
288	// under, or "" if no suitable delegate exists. Detects the cgroup from
289	// /proc/self/cgroup and walks up until it finds a writable directory.
290	// An explicit override via ORVA_CGROUPV2_MOUNT takes precedence.
291	func cgroupv2Delegate() string {
292		cgroupOnce.Do(func() {
293			if v := os.Getenv("ORVA_CGROUPV2_MOUNT"); v != "" {
294				if _, err := os.Stat(v); err == nil {
295					cgroupMount = v
296				}
297				return
298			}
299	
300			data, err := os.ReadFile("/proc/self/cgroup")
301			if err != nil {
302				return
303			}
304			// cgroup v2 line: "0::/user.slice/...".
305			var rel string
306			for _, line := range strings.Split(string(data), "\n") {
307				parts := strings.SplitN(line, ":", 3)
308				if len(parts) == 3 && parts[0] == "0" && parts[1] == "" {
309					rel = parts[2]
310					break
311				}
312			}
313			if rel == "" {
314				return
315			}
316			// Walk up from the current cgroup until we find a writable dir that
317			// actually has the controllers we need delegated to children.
318			p := filepath.Join("/sys/fs/cgroup", rel)
319			for p != "/sys/fs/cgroup" && p != "/" {
320				if isWritableDir(p) {
321					cgroupMount = p
322					return
323				}
324				p = filepath.Dir(p)
325			}
326		})
327		if cgroupMount == "" {
328			// One-time heads-up: no usable cgroup-v2 delegate, so per-sandbox
329			// memory/pid/cpu caps are NOT enforced (we fall back to rlimits). This
330			// is normal on hosts where systemd doesn't delegate controllers to the
331			// service (e.g. constrained VMs/containers); functions still run fully
332			// isolated via nsjail. Set Delegate=yes + delegate the controllers, or
333			// ORVA_CGROUPV2_MOUNT, to enable hard caps.
334			cgroupWarnOnce.Do(func() {
335				slog.Warn("cgroup v2 controllers not delegated; per-sandbox memory/pid/cpu caps disabled (rlimit-only fallback)")
336			})
337		}
338		return cgroupMount
339	}
