355	func isWritableDir(p string) bool {
356		// cgroupfs does not allow creating regular files — probe by creating a
357		// child cgroup directory and checking the kernel auto-creates cgroup.procs.
358		probe := filepath.Join(p, ".orva-cg-probe")
359		if err := os.Mkdir(probe, 0o755); err != nil {
360			return false
361		}
