402	// FindJailedCgroupPath locates the NSJAIL.* cgroup that nsjail created for
403	// its jailed child process. nsjail names the cgroup after the CHILD's PID
404	// (the Python/Node adapter process), not nsjail's own PID, so we search for
405	// a NSJAIL.* cgroup whose cgroup.procs contains a process whose parent is
406	// nsjailPid. Returns "" if not found within 500ms.
407	func FindJailedCgroupPath(mount string, nsjailPid int) string {
408		if mount == "" || nsjailPid <= 0 {
409			return ""
410		}
411		deadline := time.Now().Add(500 * time.Millisecond)
412		for time.Now().Before(deadline) {
413			entries, err := os.ReadDir(mount)
414			if err != nil {
415				return ""
416			}
417			for _, e := range entries {
418				if !strings.HasPrefix(e.Name(), "NSJAIL.") {
419					continue
420				}
421				cgPath := filepath.Join(mount, e.Name())
422				data, err := os.ReadFile(filepath.Join(cgPath, "cgroup.procs"))
423				if err != nil {
424					continue
425				}
426				for _, pidStr := range strings.Fields(string(data)) {
427					pid, err := strconv.Atoi(strings.TrimSpace(pidStr))
428					if err != nil || pid <= 0 {
429						continue
430					}
431					if procPPID(pid) == nsjailPid {
432						return cgPath
433					}
434				}
435			}
436			time.Sleep(10 * time.Millisecond)
437		}
438		return ""
439	}
