441	// procPPID returns the parent PID of the given process by reading /proc/pid/stat.
442	func procPPID(pid int) int {
443		data, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
444		if err != nil {
445			return 0
446		}
447		// Format: pid (comm) state ppid ...  — find ppid after the closing ')'
448		s := string(data)
449		if i := strings.LastIndex(s, ") "); i >= 0 {
450			fields := strings.Fields(s[i+2:])
451			if len(fields) >= 2 {
452				ppid, _ := strconv.Atoi(fields[1])
453				return ppid
454			}
455		}
456		return 0
457	}
