174	// fileSHA256 returns the hex-encoded SHA-256 of the file at path.
175	func fileSHA256(path string) (string, error) {
176		f, err := os.Open(path)
177		if err != nil {
178			return "", err
179		}
180		defer f.Close()
181		h := sha256.New()
182		if _, err := io.Copy(h, f); err != nil {
183			return "", err
184		}
185		return hex.EncodeToString(h.Sum(nil)), nil
