	checksumsBody = goodSum + "  " + asset + "\n"
	if err := downloadVerifyApply(context.Background(), rel, resolved); err != nil {
		t.Fatalf("downloadVerifyApply on resolved target: %v", err)
	}
	got, _ := os.ReadFile(real)
	if string(got) != string(newBytes) {
