44		Servers []string    `json:"servers"` // resolved IPs (v4 or v6)
45		Search  string      `json:"search"`  // optional DNS search domain
46		Records []DNSRecord `json:"records"` // host→IP overrides (beats DNS)
47		// Defaults exposed to the UI so it can show a "reset to default" hint.
48		Defaults []string `json:"defaults"`
49	}
50	
51	// LoadDNSConfig reads operator settings from system_config.
52	func LoadDNSConfig(db dbReader) DNSConfig {
53		raw := strings.TrimSpace(db.GetSystemConfigString("dns_servers", ""))
54		servers := []string{}
55		if raw != "" {
56			for _, s := range strings.Split(raw, ",") {
57				s = strings.TrimSpace(s)
58				if s != "" && net.ParseIP(s) != nil {
59					servers = append(servers, s)
60				}
61			}
62		}
63		return DNSConfig{
64			Servers:  servers,
65			Search:   strings.TrimSpace(db.GetSystemConfigString("dns_search", "")),
66			Records:  parseDNSRecords(db.GetSystemConfigString("dns_records", "")),
67			Defaults: append([]string(nil), DefaultDNSServers...),
68		}
69	}
70	
71	// parseDNSRecords decodes the on-disk "host ip" lines into structured
72	// records. Any line whose IP doesn't parse is dropped silently — the
73	// PUT handler validates strictly so this only matters if the raw config
74	// row was hand-edited.
75	func parseDNSRecords(raw string) []DNSRecord {
76		if strings.TrimSpace(raw) == "" {
77			return nil
78		}
79		out := []DNSRecord{}
80		for _, line := range strings.Split(raw, "\n") {
81			line = strings.TrimSpace(line)
82			if line == "" || strings.HasPrefix(line, "#") {
83				continue
84			}
85			fields := strings.Fields(line)
86			if len(fields) != 2 {
87				continue
88			}
89			host, ip := fields[0], fields[1]
90			if net.ParseIP(ip) == nil {
91				continue
92			}
93			out = append(out, DNSRecord{Host: host, IP: ip})
94		}
95		return out
96	}
97	
98	// SerializeDNSRecords renders records into the storage format. Public so
99	// the API handler can persist its validated input the same way LoadDNSConfig
100	// reads it.
101	func SerializeDNSRecords(records []DNSRecord) string {
102		var b strings.Builder
103		for _, r := range records {
104			fmt.Fprintf(&b, "%s %s\n", r.Host, r.IP)
105		}
106		return b.String()
107	}
108	
109	// dbReader is the small subset of *database.Database the dns layer
110	// needs. Keeping it as an interface lets tests stub it without pulling
111	// in the whole DB.
112	type dbReader interface {
113		GetSystemConfigString(key, fallback string) string
114	}
115	
116	// WriteResolvConf renders the resolv.conf file the sandbox bind-mounts.
117	// Falls back to DefaultDNSServers when the operator has cleared the
118	// list — we never want to leave a sandbox with no resolver, since
119	// without DNS a function with network_mode=egress is half-broken.
120	//
121	// File is written atomically: temp + rename. Same content + same mode
122	// is a no-op (we still rewrite for simplicity; nstun reads on each
123	// spawn so there's no hot-reload race).
124	func WriteResolvConf(dataDir string, cfg DNSConfig) error {
125		servers := cfg.Servers
126		if len(servers) == 0 {
127			servers = DefaultDNSServers
128		}
129	
130		var b strings.Builder
131		b.WriteString("# Generated by orva firewall manager. Edit DNS via the\n")
132		b.WriteString("# Firewall page in the UI or PUT /api/v1/firewall/dns.\n")
133		if cfg.Search != "" {
134			fmt.Fprintf(&b, "search %s\n", cfg.Search)
135		}
136		for _, s := range servers {
137			fmt.Fprintf(&b, "nameserver %s\n", s)
138		}
139		b.WriteString("options edns0 timeout:2 attempts:2\n")
140	
141		target := ResolvConfPath(dataDir)
142		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
143			return err
144		}
145		tmp := target + ".tmp"
146		if err := os.WriteFile(tmp, []byte(b.String()), 0o644); err != nil {
147			return err
148		}
149		return os.Rename(tmp, target)
150	}
151	
152	// WriteHostsFile renders the operator's host→IP overrides into a
153	// /etc/hosts-format file egress sandboxes bind-mount at /etc/hosts. The
154	// glibc/musl resolver consults files before DNS by default, so any record
155	// here wins over upstream resolution — exactly the override contract the
156	// UI promises.
157	//
158	// We always write a baseline localhost block so the in-sandbox resolver
159	// behaves sanely even if the operator clears their custom records.
160	func WriteHostsFile(dataDir string, records []DNSRecord) error {
161		var b strings.Builder
162		b.WriteString("# Generated by orva firewall manager. Edit DNS records via\n")
163		b.WriteString("# the Firewall page in the UI or PUT /api/v1/firewall/dns.\n")
164		b.WriteString("# Operator-defined entries below override any upstream DNS.\n\n")
165		b.WriteString("127.0.0.1   localhost\n")
166		b.WriteString("::1         localhost ip6-localhost ip6-loopback\n")
167		if len(records) > 0 {
168			b.WriteString("\n# Custom records\n")
169			for _, r := range records {
170				fmt.Fprintf(&b, "%s   %s\n", r.IP, r.Host)
171			}
172		}
173	
174		target := HostsFilePath(dataDir)
175		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
176			return err
177		}
178		tmp := target + ".tmp"
179		if err := os.WriteFile(tmp, []byte(b.String()), 0o644); err != nil {
180			return err
181		}
182		return os.Rename(tmp, target)
183	}
