	}
	for _, r := range rules {
		if !r.matchAll && !r.dst.Contains(addr) {
			continue
		}
		// A port-scoped rule cannot decide a bare-address question; the
		// dialer's Control hook does know the port, but treating a narrow
		// carve-out as a blanket verdict either way would be wrong, so
		// port-scoped rules are skipped here.
		if r.dport != 0 {
			continue
		}
		return r.act == actionReject
	}
	return false // NSTUN's no-match default
}

