	}
	// And it must still reach the jail, by name.
	for _, name := range []string{"NPM_CONFIG__AUTH", "HTTPS_PROXY"} {
		if !hasPair(args, "--env", name) {
			t.Errorf("%s must still be forwarded to the jail via the pass-through form", name)
