// getting no endpoint check at all.
func defaultPreflightRoot(provider string) string {
	if r := defaultRoot(provider); r != "" {
		return r
	}
	switch strings.ToLower(provider) {
	case "gemini":
		return "https://generativelanguage.googleapis.com"
	}
	return ""
